import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Navbar({ userRole }) {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false); // for admin submenu

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  return (
    <nav className="bg-white shadow">
      <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* Brand */}
        <Link to="/dashboard" className="text-2xl font-bold text-blue-600">
          CampusConnect
        </Link>

        {/* Hamburger for mobile */}
        <div className="md:hidden">
          <button
            onClick={() => setMenuOpen(!menuOpen)}
            className="text-gray-700 hover:text-blue-600 focus:outline-none"
          >
            {menuOpen ? (
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            ) : (
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8h16M4 16h16" />
              </svg>
            )}
          </button>
        </div>

        {/* Menu */}
        <ul
          className={`flex-col md:flex md:flex-row md:items-center md:gap-6 w-full md:w-auto ${
            menuOpen ? "flex" : "hidden"
          }`}
        >
          {/* Student links */}
          {userRole === "student" && (
            <>
              <li>
                <Link
                  to="/dashboard"
                  onClick={() => setMenuOpen(false)}
                  className="block px-4 py-2 text-gray-700 hover:text-blue-600"
                >
                  Dashboard
                </Link>
              </li>
              <li>
                <Link
                  to="/support"
                  onClick={() => setMenuOpen(false)}
                  className="block px-4 py-2 text-gray-700 hover:text-blue-600"
                >
                  Support
                </Link>
              </li>
              <li>
                <Link
                  to="/feedback"
                  onClick={() => setMenuOpen(false)}
                  className="block px-4 py-2 text-gray-700 hover:text-blue-600"
                >
                  Feedback
                </Link>
              </li>
            </>
          )}

          {/* Admin links */}
          {userRole === "admin" && (
            <>
              <li className="relative">
                <button
                  onClick={() => setDropdownOpen(!dropdownOpen)}
                  className="flex items-center px-4 py-2 text-gray-700 hover:text-blue-600 md:after:content-['▾']"
                >
                  Admin Dashboard
                </button>

                {/* Dropdown */}
                <ul
                  className={`absolute md:top-full left-0 bg-white shadow-md rounded mt-2 md:min-w-[180px] z-50 ${
                    dropdownOpen ? "block" : "hidden"
                  }`}
                >
                  <li>
                    <Link
                      to="/admin-dashboard"
                      className="block px-4 py-2 hover:bg-blue-50"
                      onClick={() => {
                        setMenuOpen(false);
                        setDropdownOpen(false);
                      }}
                    >
                      Overview
                    </Link>
                  </li>
                  <li>
                    <Link
                      to="/admin-announcements"
                      className="block px-4 py-2 hover:bg-blue-50"
                      onClick={() => {
                        setMenuOpen(false);
                        setDropdownOpen(false);
                      }}
                    >
                      Announcements
                    </Link>
                  </li>
                  <li>
                    <Link
                      to="/admin-students"
                      className="block px-4 py-2 hover:bg-blue-50"
                      onClick={() => {
                        setMenuOpen(false);
                        setDropdownOpen(false);
                      }}
                    >
                      Student Profiles
                    </Link>
                  </li>
                </ul>
              </li>
            </>
          )}

          {/* Logout */}
          <li className="px-4 py-2 md:py-0">
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 w-full md:w-auto"
            >
              Logout
            </button>
          </li>
        </ul>
      </div>
    </nav>
  );
}

export default Navbar;
